import {
  evalDigest,
  evalHistoryRecordIssues,
  evalExecutionSucceeded,
} from "./evidence.js";

export const OUTCOME_PLAN_SCHEMA = "chainlesschain.outcome-plan/v1";
export const OUTCOME_REPORT_SCHEMA = "chainlesschain.outcome-report/v1";
const DIGEST = /^sha256:[a-f0-9]{64}$/u;
const CATEGORIES = new Set([
  "repair",
  "support",
  "compatibility",
  "release",
  "test-infrastructure",
  "construction",
]);
const STAGES = ["install", "configure", "authenticate", "tool", "artifact"];
const FAILURE_CAUSES = new Set([
  "install",
  "configuration-identity",
  "model-protocol",
  "tools-permissions",
  "retrieval-context",
  "recovery",
  "artifact",
  "environment",
  "budget",
  "manual-repair",
]);
const nonempty = (value) =>
  typeof value === "string" && value.trim().length > 0;
const nonnegative = (value) => Number.isFinite(value) && value >= 0;
const count = (value) => Number.isSafeInteger(value) && value >= 0;
const rate = (numerator, denominator) =>
  denominator ? numerator / denominator : null;
function assert(value, message) {
  if (!value) throw new Error(message);
}
function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  if (!value || typeof value !== "object") return value;
  return Object.fromEntries(
    Object.keys(value)
      .sort()
      .map((key) => [key, canonical(value[key])]),
  );
}
export function outcomeDigest(value) {
  return evalDigest(JSON.stringify(canonical(value)));
}
function epoch(value) {
  const time = Date.parse(value);
  return typeof value === "string" &&
    Number.isFinite(time) &&
    new Date(time).toISOString() === value
    ? time
    : NaN;
}
function uniqueIndex(rows, key, label) {
  assert(Array.isArray(rows), `${label} must be an array`);
  const index = new Map();
  for (const row of rows) {
    assert(
      row && nonempty(row[key]) && !index.has(row[key]),
      `${label} contains a missing or duplicate ${key}`,
    );
    index.set(row[key], row);
  }
  return index;
}

export function validateOutcomePlan(plan) {
  assert(plan?.schema === OUTCOME_PLAN_SCHEMA, "invalid outcome plan schema");
  assert(
    /^[a-f0-9]{40}$/u.test(plan.commitSha || ""),
    "plan requires an exact commit SHA",
  );
  assert(/^[A-Z]{3}$/u.test(plan.currency || ""), "plan requires one currency");
  assert(
    epoch(plan.window?.start) < epoch(plan.window?.end),
    "invalid observation window",
  );
  const samples = uniqueIndex(plan.samples, "id", "plan samples");
  assert(
    samples.size > 0 && samples.size <= 10000,
    "plan requires 1–10000 samples",
  );
  for (const sample of samples.values()) {
    assert(["task", "first-run"].includes(sample.kind), "invalid sample kind");
    assert(
      nonempty(sample.taskId) && nonempty(sample.stratum),
      "sample requires taskId and stratum",
    );
    assert(
      DIGEST.test(sample.comparisonDigest || ""),
      "sample requires an Eval comparison digest",
    );
    assert(
      nonnegative(sample.costBudget) &&
        Number.isFinite(sample.timeBudgetMs) &&
        sample.timeBudgetMs > 0,
      "sample requires finite cost and time budgets",
    );
  }
  return samples;
}

function summarize(rows) {
  const succeeded = rows.filter((row) => row.succeeded).length;
  const observed = rows.filter((row) => row.observed).length;
  const knownCost = rows.reduce((sum, row) => sum + (row.cost ?? 0), 0);
  const costsComplete = rows.every((row) => row.observed && row.cost !== null);
  return {
    planned: rows.length,
    observed,
    missing: rows.length - observed,
    succeeded,
    successRate: rate(succeeded, rows.length),
    knownCost,
    totalCost: costsComplete ? knownCost : null,
    costPerSuccess: costsComplete && succeeded ? knownCost / succeeded : null,
    retries: rows.every((row) => row.retries !== null)
      ? rows.reduce((sum, row) => sum + row.retries, 0)
      : null,
    manualRepairs: rows.every((row) => row.manualRepairs !== null)
      ? rows.reduce((sum, row) => sum + row.manualRepairs, 0)
      : null,
  };
}

/** Read-only measurement. Declarations and local Eval files are not attestations. */
export function buildOutcomeReport(
  { plan, history, observations = [], maintenance = null },
  { now = Date.now(), expectedPlanDigest } = {},
) {
  const samples = validateOutcomePlan(plan);
  assert(Number.isFinite(now), "invalid report time");
  const planDigest = outcomeDigest(plan);
  assert(
    !expectedPlanDigest || expectedPlanDigest === planDigest,
    "frozen plan digest mismatch",
  );
  const observed = uniqueIndex(observations, "sampleId", "observations");
  for (const id of observed.keys())
    assert(samples.has(id), "observation is outside the frozen plan");
  const runs = uniqueIndex(history?.runs ?? [], "runId", "Eval history");
  const issues = (history?.issues ?? []).map((issue) => issue.code);
  if (epoch(plan.window.end) > now)
    issues.push("observation_window_not_closed");
  const usedEvidence = new Set();
  const rows = [];
  for (const sample of samples.values()) {
    const observation = observed.get(sample.id);
    const reasons = [];
    const row = {
      sampleId: sample.id,
      kind: sample.kind,
      taskId: sample.taskId,
      stratum: sample.stratum,
      observed: Boolean(observation),
      succeeded: false,
      reasons,
      cost: null,
      elapsedMs: null,
      retries: null,
      manualRepairs: null,
      failureCause: null,
      firstRunCompletedStages: [],
    };
    rows.push(row);
    if (!observation) {
      reasons.push("missing_observation");
      issues.push(`${sample.id}:missing_observation`);
      continue;
    }
    for (const key of ["cost", "elapsedMs", "retries", "manualRepairs"]) {
      const valid = ["retries", "manualRepairs"].includes(key)
        ? count(observation[key])
        : nonnegative(observation[key]);
      if (valid) row[key] = observation[key];
      else reasons.push(`missing_or_invalid_${key}`);
    }
    const observedAt = epoch(observation.observedAt);
    if (!(
      observedAt <= Math.min(now, epoch(plan.window.end)) &&
      observedAt - (row.elapsedMs ?? 0) >= epoch(plan.window.start)
    ))
      reasons.push("observation_outside_window");
    const run = runs.get(observation.runId);
    const stoppedBeforeTask =
      sample.kind === "first-run" &&
      observation.runId === null &&
      observation.firstRun?.stages?.tool?.passed === false;
    const evidenceKey = JSON.stringify([observation.runId, sample.taskId]);
    if (observation.runId !== null) {
      assert(
        !usedEvidence.has(evidenceKey),
        "a task execution cannot count as multiple samples",
      );
      usedEvidence.add(evidenceKey);
    }
    if (!run && !stoppedBeforeTask) reasons.push("missing_eval_run");
    if (run) {
      // Failed executions are valid observations, not successful outcomes.
      // All other existing Eval integrity rules remain authoritative.
      const integrity = evalHistoryRecordIssues(
        run,
        now,
        Math.max(1, now - epoch(plan.window.start)),
      ).filter((reason) => reason !== "execution_not_successful");
      reasons.push(...integrity);
      if (run.label !== plan.commitSha) reasons.push("commit_mismatch");
      if (outcomeDigest(run.comparison) !== sample.comparisonDigest)
        reasons.push("comparison_mismatch");
      if (!(
        epoch(run.ranAt) >= epoch(plan.window.start) &&
        epoch(run.ranAt) <= epoch(plan.window.end)
      ))
        reasons.push("run_outside_window");
    }
    const result = run?.results?.find((item) => item?.id === sample.taskId);
    if (!result && !stoppedBeforeTask) reasons.push("missing_task_result");
    if (result && (!nonnegative(result.ms) || row.elapsedMs < result.ms))
      reasons.push("invalid_elapsed_time");
    if (sample.kind === "first-run") {
      if (typeof observation.firstRun?.cleanEnvironment !== "boolean")
        reasons.push("missing_clean_environment_evidence");
      for (const stage of STAGES) {
        const evidence = observation.firstRun?.stages?.[stage];
        if (
          !evidence ||
          typeof evidence.passed !== "boolean" ||
          !nonempty(evidence.receipt)
        )
          reasons.push(`missing_stage_evidence:${stage}`);
        else if (evidence.passed) row.firstRunCompletedStages.push(stage);
      }
      // A later completed stage without its prerequisites is not a valid funnel.
      if (
        row.firstRunCompletedStages.some(
          (stage, index) => stage !== STAGES[index],
        )
      )
        reasons.push("inconsistent_first_run_stages");
    }
    for (const reason of reasons) issues.push(`${sample.id}:${reason}`);
    const successfulExecution =
      result?.pass === true &&
      result.artifactCheckPassed === true &&
      evalExecutionSucceeded(result) &&
      result.executionEvidence.observedFallback === false;
    if (!successfulExecution) reasons.push("task_not_successful");
    if (row.elapsedMs > sample.timeBudgetMs || row.cost > sample.costBudget)
      reasons.push("budget_exceeded");
    if (row.manualRepairs > 0) reasons.push("manual_repair");
    if (
      sample.kind === "first-run" &&
      (observation.firstRun?.cleanEnvironment !== true ||
        row.firstRunCompletedStages.length !== STAGES.length)
    )
      reasons.push("first_run_not_completed");
    row.succeeded = reasons.length === 0;
    if (!row.succeeded) {
      if (FAILURE_CAUSES.has(observation.failureCause))
        row.failureCause = observation.failureCause;
      else issues.push(`${sample.id}:missing_failure_cause`);
    }
  }
  const categories = Object.fromEntries(
    [...CATEGORIES].map((category) => [category, 0]),
  );
  let maintenanceComplete = false;
  if (maintenance) {
    const entries = uniqueIndex(
      maintenance.entries,
      "id",
      "maintenance entries",
    );
    maintenanceComplete =
      maintenance.complete === true &&
      outcomeDigest(maintenance.window) === outcomeDigest(plan.window);
    for (const entry of entries.values()) {
      assert(
        CATEGORIES.has(entry.category) &&
          nonnegative(entry.hours) &&
          nonempty(entry.evidenceRef),
        "invalid maintenance entry",
      );
      categories[entry.category] += entry.hours;
    }
  }
  if (!maintenanceComplete) issues.push("incomplete_maintenance_records");
  const maintenanceHours = [...CATEGORIES]
    .filter((category) => category !== "construction")
    .reduce((sum, category) => sum + categories[category], 0);
  const attempts = rows.filter((row) => row.observed).length;
  const allObserved = rows.every((row) => row.observed);
  const firstRuns = rows.filter((row) => row.kind === "first-run");
  const tasks = rows.filter((row) => row.kind === "task");
  if (!firstRuns.length || !tasks.length)
    issues.push("missing_metric_population");
  return {
    schema: OUTCOME_REPORT_SCHEMA,
    generatedAt: new Date(now).toISOString(),
    scope: "local-outcome-baseline",
    productionAttested: false,
    status: issues.length ? "INSUFFICIENT_EVIDENCE" : "BASELINE_RECORDED",
    // Neither a baseline nor operator declarations constitute an improvement gate.
    improvementVerdict: "NOT_EVALUATED",
    planDigest,
    commitSha: plan.commitSha,
    currency: plan.currency,
    window: plan.window,
    task: summarize(tasks),
    firstRun: summarize(firstRuns),
    maintenance: {
      complete: maintenanceComplete,
      knownHours: maintenanceHours,
      totalHours: maintenanceComplete ? maintenanceHours : null,
      per100Attempts:
        maintenanceComplete && allObserved && attempts
          ? (maintenanceHours / attempts) * 100
          : null,
      observedAttempts: attempts,
      constructionHours: maintenanceComplete ? categories.construction : null,
      categories,
    },
    groups: [
      ...new Set(
        rows.map((row) => JSON.stringify([row.kind, row.stratum, row.taskId])),
      ),
    ].map((key) => {
      const [kind, stratum, taskId] = JSON.parse(key);
      return {
        kind,
        stratum,
        taskId,
        ...summarize(
          rows.filter(
            (row) =>
              row.kind === kind &&
              row.stratum === stratum &&
              row.taskId === taskId,
          ),
        ),
      };
    }),
    firstRunFunnel: STAGES.map((stage, index) => ({
      stage,
      planned: firstRuns.length,
      passed: firstRuns.filter((row) =>
        STAGES.slice(0, index + 1).every((required) =>
          row.firstRunCompletedStages.includes(required),
        ),
      ).length,
    })),
    failureCauses: [
      ...new Set(
        rows
          .filter((row) => !row.succeeded)
          .map((row) => row.failureCause || "unknown"),
      ),
    ].map((cause) => ({
      cause,
      count: rows.filter(
        (row) => !row.succeeded && (row.failureCause || "unknown") === cause,
      ).length,
    })),
    issues: [...new Set(issues)],
    rows,
  };
}

import { createHash, randomUUID } from "node:crypto";
import fs from "node:fs";
import { computeTrend } from "./trend.js";
import { redactSecrets } from "../secret-scan.js";

export const EVAL_HISTORY_SCHEMA = "chainlesschain.eval-history/v1";
export const EVAL_CONTEXT_SCHEMA = "chainlesschain.eval-comparison-context/v1";
export const EVAL_COMPARISON_SCHEMA = "chainlesschain.eval-comparison/v1";
export const EVAL_EXECUTION_PROTOCOL = "cc-agent-stream-json/v1";
const DIGEST = /^sha256:[a-f0-9]{64}$/u;
const MAX_HISTORY_BYTES = 16 * 1024 * 1024;
const CONTEXT_KEYS = [
  "schema",
  "provider",
  "model",
  "modelRevision",
  "environmentDigest",
  "permissionDigest",
  "inferenceDigest",
];

function canonical(value) {
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
  if (value && typeof value === "object") {
    return `{${Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${canonical(value[key])}`)
      .join(",")}}`;
  }
  return JSON.stringify(value);
}

export function evalDigest(value) {
  return `sha256:${createHash("sha256").update(value).digest("hex")}`;
}

function nonempty(value) {
  return (
    typeof value === "string" && value.trim().length > 0 && value.length <= 1024
  );
}

/** These are operator declarations, not observed provider state or PKI proofs. */
export function validateComparisonContext(value, { provider, model } = {}) {
  if (
    !value ||
    typeof value !== "object" ||
    Array.isArray(value) ||
    Object.keys(value).length !== CONTEXT_KEYS.length ||
    Object.keys(value).some((key) => !CONTEXT_KEYS.includes(key)) ||
    value.schema !== EVAL_CONTEXT_SCHEMA ||
    ![value.provider, value.model, value.modelRevision].every(nonempty) ||
    ![
      value.environmentDigest,
      value.permissionDigest,
      value.inferenceDigest,
    ].every((v) => DIGEST.test(v || ""))
  ) {
    throw new Error(
      "comparison context requires its v1 schema, provider, model, modelRevision and environment/permission/inference sha256 digests",
    );
  }
  if (
    (provider !== undefined && value.provider !== provider) ||
    (model !== undefined && value.model !== model)
  ) {
    throw new Error(
      "comparison context must match explicit --provider and --model",
    );
  }
  return { ...value };
}

export function readComparisonContext(file, selection) {
  if (fs.statSync(file).size > 16 * 1024)
    throw new Error("comparison context exceeds its size limit");
  const bytes = fs.readFileSync(file);
  if (bytes.length === 0 || bytes.length > 16 * 1024) {
    throw new Error("comparison context exceeds its size limit");
  }
  return validateComparisonContext(
    JSON.parse(bytes.toString("utf8")),
    selection,
  );
}

export function createEvalComparison({
  suite,
  corpusDigest,
  provider,
  model,
  context,
  platform = process.platform,
  arch = process.arch,
  node = process.version,
} = {}) {
  if (!context) return null;
  if (!nonempty(provider) || !nonempty(model)) {
    throw new Error(
      "--comparison-context requires explicit --provider and --model",
    );
  }
  if (!nonempty(suite) || !DIGEST.test(corpusDigest || ""))
    throw new Error("eval corpus identity is required");
  const declared = validateComparisonContext(context, { provider, model });
  return {
    schema: EVAL_COMPARISON_SCHEMA,
    basis: "local-runtime-and-operator-declarations",
    suite,
    corpusDigest,
    provider,
    model,
    runtime: { platform, arch, node },
    permissionMode: "acceptEdits",
    executionProtocol: EVAL_EXECUTION_PROTOCOL,
    declared,
  };
}

export function createEvalHistoryRecord(
  summary,
  {
    comparison = null,
    dryRun = false,
    label = null,
    ranAt = new Date().toISOString(),
    runId = randomUUID(),
  } = {},
) {
  return {
    schema: EVAL_HISTORY_SCHEMA,
    runId,
    ranAt,
    label,
    dryRun,
    comparison,
    passed: summary.passed,
    failed: summary.failed,
    total: summary.total,
    passRate: summary.passRate,
    unrelatedChangeRate: summary.unrelatedChangeRate,
    results: summary.results.map((result) => ({
      id: result.id,
      pass: result.pass,
      artifactCheckPassed: result.artifactCheckPassed,
      executionSucceeded: result.executionSucceeded,
      agentOk: result.agentOk,
      executionEvidence: result.executionEvidence,
      usage: result.usage ?? null,
      totalCostUsd: Number.isFinite(result.totalCostUsd)
        ? result.totalCostUsd
        : null,
      error:
        result.error == null
          ? null
          : redactSecrets(String(result.error)).slice(0, 2048),
      detail: redactSecrets(String(result.detail || "")).slice(0, 2048),
      ms: result.ms,
      changedFiles: result.changedFiles,
      unrelatedChanges: result.unrelatedChanges,
    })),
  };
}

/** Diagnostic callers may inspect valid rows, but must keep parse issues. */
export function parseEvalHistory(text) {
  const runs = [],
    issues = [];
  if (Buffer.byteLength(text, "utf8") > MAX_HISTORY_BYTES) {
    return { runs, issues: [{ code: "history_too_large" }] };
  }
  text.split(/\r?\n/u).forEach((line, index) => {
    if (!line.trim()) return;
    try {
      const value = JSON.parse(line);
      if (!value || typeof value !== "object" || Array.isArray(value))
        throw new Error("not a record");
      runs.push(value);
    } catch {
      issues.push({ code: "invalid_history_record", line: index + 1 });
    }
  });
  return { runs, issues };
}

export function readEvalHistory(file) {
  if (!fs.existsSync(file)) return { runs: [], issues: [] };
  if (fs.statSync(file).size > MAX_HISTORY_BYTES) {
    return { runs: [], issues: [{ code: "history_too_large" }] };
  }
  return parseEvalHistory(fs.readFileSync(file, "utf8"));
}

function validateComparison(value) {
  try {
    const rebuilt = createEvalComparison({
      suite: value?.suite,
      corpusDigest: value?.corpusDigest,
      provider: value?.provider,
      model: value?.model,
      context: value?.declared,
      platform: value?.runtime?.platform,
      arch: value?.runtime?.arch,
      node: value?.runtime?.node,
    });
    return (
      rebuilt &&
      Object.values(value.runtime).every(nonempty) &&
      canonical(rebuilt) === canonical(value)
    );
  } catch {
    return false;
  }
}

export function evalExecutionSucceeded(result) {
  const execution = result?.executionEvidence;
  return (
    result?.executionSucceeded === true &&
    result.error === null &&
    execution?.protocol === EVAL_EXECUTION_PROTOCOL &&
    execution.exitCode === 0 &&
    execution.signal === null &&
    execution.terminalVerified === true
  );
}

export function evalHistoryRecordIssues(record, now, maxAgeMs) {
  if (!record || typeof record !== "object" || Array.isArray(record))
    return ["invalid_history_record"];
  const issues = [];
  if (record.schema !== EVAL_HISTORY_SCHEMA || !nonempty(record.runId))
    issues.push("legacy_or_missing_run_identity");
  if (record.dryRun !== false) issues.push("dry_run_or_missing_execution_mode");
  const epoch = Date.parse(record.ranAt);
  if (
    typeof record.ranAt !== "string" ||
    !Number.isFinite(epoch) ||
    new Date(epoch).toISOString() !== record.ranAt ||
    epoch > now ||
    now - epoch > maxAgeMs
  )
    issues.push("invalid_or_expired_evidence");
  if (!validateComparison(record.comparison))
    issues.push("missing_comparison_identity");
  const results = record.results;
  if (!Array.isArray(results) || results.length === 0)
    return [...issues, "missing_task_results"];
  const ids = new Set();
  let passed = 0;
  for (const result of results) {
    if (!result || !nonempty(result.id) || ids.has(result.id)) {
      issues.push("invalid_or_duplicate_task");
      continue;
    }
    ids.add(result.id);
    const execution = result.executionEvidence;
    if (
      typeof result.pass !== "boolean" ||
      typeof result.artifactCheckPassed !== "boolean" ||
      typeof result.executionSucceeded !== "boolean" ||
      result.agentOk !== result.executionSucceeded ||
      result.pass !== (result.artifactCheckPassed && result.executionSucceeded)
    )
      issues.push("inconsistent_task_verdict");
    if (!evalExecutionSucceeded(result))
      issues.push("execution_not_successful");
    if (execution?.observedFallback !== false)
      issues.push("fallback_or_missing_model_continuity");
    if (result.pass === true) passed += 1;
  }
  if (
    record.total !== results.length ||
    record.passed !== passed ||
    record.failed !== results.length - passed ||
    record.passRate !== passed / results.length
  )
    issues.push("inconsistent_task_totals");
  return issues;
}

/**
 * A local comparison gate. It does not attest model checkpoints, configuration
 * declarations, edited JSONL, hidden holdouts, or production release authority.
 * Append order selects the pair; timestamps cannot silently select older rows.
 */
export function evaluateStrictEvalGate(
  { runs = [], issues = [] } = {},
  {
    now = Date.now(),
    maxAgeMs = 7 * 24 * 60 * 60 * 1000,
    regressionThreshold = 0,
  } = {},
) {
  const reasons = issues.map((issue) => issue.code);
  if (
    !Number.isFinite(now) ||
    !Number.isFinite(maxAgeMs) ||
    maxAgeMs <= 0 ||
    !Number.isFinite(regressionThreshold) ||
    regressionThreshold < 0 ||
    regressionThreshold > 1
  )
    reasons.push("invalid_gate_options");
  if (!Array.isArray(runs) || runs.length < 2) reasons.push("missing_baseline");
  const pair = Array.isArray(runs) ? runs.slice(-2) : [];
  for (const record of pair)
    reasons.push(...evalHistoryRecordIssues(record, now, maxAgeMs));
  if (pair.length === 2) {
    const [baseline, candidate] = pair;
    if (
      baseline?.runId === candidate?.runId ||
      Date.parse(baseline?.ranAt) >= Date.parse(candidate?.ranAt)
    )
      reasons.push("duplicate_or_unordered_runs");
    if (canonical(baseline?.comparison) !== canonical(candidate?.comparison))
      reasons.push("comparison_identity_changed");
    const ids = (record) =>
      (Array.isArray(record?.results) ? record.results : [])
        .map((r) => r?.id)
        .sort();
    if (canonical(ids(baseline)) !== canonical(ids(candidate)))
      reasons.push("task_population_changed");
  }
  const uniqueReasons = [...new Set(reasons)];
  const base = {
    scope: "local-eval-comparison",
    productionAttested: false,
    baselineRunId: pair.length === 2 ? pair[0]?.runId || null : null,
    candidateRunId: pair.at(-1)?.runId || null,
  };
  if (uniqueReasons.length)
    return {
      ...base,
      status: "INSUFFICIENT_EVIDENCE",
      passed: false,
      reasons: uniqueReasons,
    };
  const trend = computeTrend(pair, { regressionThreshold });
  const failed = trend.regressed || pair[1].passed !== pair[1].total;
  return {
    ...base,
    status: failed ? "FAIL" : "PASS",
    passed: !failed,
    reasons: failed
      ? [trend.regressed ? "task_regression" : "candidate_tasks_failed"]
      : [],
    trend,
  };
}

